namespace ghidra.app.plugin.core.decompiler.taint.slicetree;







using docking.widgets.tree;
using generic.theme;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.util;
using ghidra.util.exception;
using ghidra.util.task;

public class LeafSliceNode : SliceNode {

	// A stop sign symbol without the word stop.
	private static readonly Icon ICON = new GIcon("icon.plugin.calltree.node.dead.end");

	private Reference reference;
	private string name;

	private Program program;

	LeafSliceNode(Program program, Reference reference) {
		// Leaf node is the 0 level, OR cannot expand.
		super(new AtomicInteger(0));
		this.program = program;
		this.reference = reference;
	}

	/* @Override */
	public SliceNode recreate() {
		return new LeafSliceNode(program, reference);
	}

	/* @Override */
	public Function getRemoteFunction() {
		return null; // no function--dead end
	}

	/**
	 * The address from which this leaf node comes.
	 */
	/* @Override */
	public Address getSourceAddress() {
		return reference.getFromAddress();
	}

	/* @Override */
	public Icon getIcon(bool expanded) {
		return ICON;
	}

	/**
	 * Name of the symbol associated with the to address or the to address as a string 
	 * in cases where there is no symbol.
	 */
	/* @Override */
	public string getName() {
		if (name == null) {
			Address toAddress = reference.getToAddress();
			SymbolTable symbolTable = program.getSymbolTable();
			Symbol symbol = symbolTable.getPrimarySymbol(toAddress);
			if (symbol != null) {
				name = symbol.getName();
			}
			else {
				name = toAddress.toString();
			}
		}
		return name;
	}

	/* @Override */
	public string getToolTip() {
		return "Called from " + reference.getFromAddress();
	}

	/* @Override */
	public bool isLeaf() {
		return true;
	}

	/* @Override */
	public ProgramLocation getLocation() {
		return new ProgramLocation(program, reference.getToAddress());
	}

	/**
	 * There are no children
	 */
	/* @Override */
	public List<GTreeNode> generateChildren(TaskMonitor monitor)
    {
		return new();
	}
}
